#include <stdio.h>
#include <string.h>

void parse_heading(char *line) {
    int level = 0;
    while (line[level] == '#') level++;
    if (level > 0 && level <= 3) {
        char *content = line + level;
        while (*content == ' ') content++;
        printf("<h%d>%s</h%d>\n", level, content, level);
    } else {
        printf("%s\n", line);
    }
}

int main() {
    parse_heading("# Title");
    parse_heading("## Section");
    parse_heading("### Subsection");
    return 0;
}
